 "content": "def transform(grid):
    """Extend a solid color-2 rectangle along rows and columns.

    Rays from the rectangle extend to the grid edge unless a color-1
    marker lies on that side of the same row/column; then that side is
    blocked, and the opposite side still extends.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return out
    rows = sorted({r for r, _ in cells})
    cols = sorted({c for _, c in cells})
    rmin, rmax = min(rows), max(rows)
    cmin, cmax = min(cols), max(cols)

    # Extend each occupied row horizontally, with markers blocking their side.
    for r in rows:
        left_blocked = any(grid[r][c] == 1 for c in range(cmin))
        right_blocked = any(grid[r][c] == 1 for c in range(cmax + 1, w))
        if not left_blocked:
            for c in range(cmin):
                if grid[r][c] == 0:
                    out[r][c] = 2
        if not right_blocked:
            for c in range(cmax + 1, w):
                if grid[r][c] == 0:
                    out[r][c] = 2

    # Extend each occupied column vertically, with markers blocking their side.
    for c in cols:
        top_blocked = any(grid[r][c] == 1 for r in range(rmin))
        bottom_blocked = any(grid[r][c] == 1 for r in range(rmax + 1, h))
        if not top_blocked:
            for r in range(rmin):
                if grid[r][c] == 0:
                    out[r][c] = 2
        if not bottom_blocked:
            for r in range(rmax + 1, h):
                if grid[r][c] == 0:
                    out[r][c] = 2
    return out
